cd /
echo "== intel2 default keys"; ls ~/.ssh/ | grep -E '^id_' ; 
echo "== epyc2 reachable from intel2"; ssh -n -o ControlPath=none -o ConnectTimeout=10 epyc2 'hostname; docker images --format "{{.Repository}}:{{.Tag}} {{.ID}}" | head -12; du -sh ~/.local/opentallas-tools ~/.local/lib ~/.local/bin 2>/dev/null; ls ~/.ssh | grep -E "^id_"; df -h /srv/opentallas-scratch2 /srv/opentallas-scratch3 | tail -2; md5sum /usr/local/bin/ot-heavy /usr/local/bin/ot-heavy-reconcile; ls ~/ot-fleet-install 2>/dev/null | head; crontab -l | grep -v "^#" | cut -c1-140; docker --version; apt-mark showmanual | wc -l; ls -la ~/.local/opentallas-tools | head -20'
echo "== epyc6"; ssh -n -o ControlPath=none -o ConnectTimeout=10 epyc6 'ls ~/ot-fleet-install 2>/dev/null | head; wc -l ~/.ssh/authorized_keys; awk "{print \$1, \$NF}" ~/.ssh/authorized_keys | cut -c1-60; grep -v "^#" ~/.ssh/config | cut -c1-80; grep -n opentallas ~/.bashrc | cut -c1-200; md5sum /usr/local/bin/ot-heavy /usr/local/bin/ot-heavy-reconcile; apt-mark showmanual | wc -l; systemctl is-enabled ot-autoclean.timer ot-lifecycle.timer 2>&1 | head -3; systemctl is-active earlyoom ot-die-protection 2>&1 | head; ls -la ~/OpenTallas; ls /etc/systemd/system/ | grep -E "ot-|docker|containerd"; cat /etc/docker/daemon.json 2>/dev/null | head -20; grep -E "ubuntu" /etc/sudoers.d/* 2>/dev/null | cut -c1-100'
echo "== hub repo"; git -C ~/OpenTallas rev-parse --short HEAD; du -sh ~/OpenTallas/.git 2>/dev/null
echo "== hosts lists"; grep -n 'epyc6' ~/.local/bin/ot-sizes-sync ~/.local/bin/ot-reserve | cut -c1-180
